import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../app/providers.dart';
import '../../../core/widgets/app_async_state.dart';import '../../../data/models/assessment_model.dart';
final assessmentsProvider=StreamProvider<List<AssessmentModel>>((ref)=>ref.watch(assessmentRepositoryProvider).watchActive());
class AssessmentListScreen extends ConsumerWidget{const AssessmentListScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final state=ref.watch(assessmentsProvider);return Scaffold(appBar:AppBar(title:const Text('الاختبارات التعليمية')),body:state.when(loading:()=>const AppLoading(),error:(e,_)=>AppErrorState(message:'تعذر تحميل الاختبارات.',onRetry:()=>ref.invalidate(assessmentsProvider)),data:(items)=>items.isEmpty?const AppEmptyState(title:'لا توجد اختبارات متاحة',message:'ستظهر الاختبارات التي ينشرها فريق الإدارة هنا.',icon:Icons.quiz_outlined):ListView.separated(padding:const EdgeInsets.all(20),itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(height:12),itemBuilder:(_,index){final item=items[index];return Card(child:ListTile(title:Text(item.title),subtitle:Text(item.description),trailing:const Icon(Icons.arrow_back_ios_new),onTap:()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('يتم حفظ إجابات الاختبار ونتيجته في Firestore.'))));})));}}
